<script lang="ts">
 import { onMount } from 'svelte'; import { request } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Field={key:string;label:string;kind:'text'|'textarea'|'number'|'date'|'select';required:boolean;options:string[]}; type Template={id:string;title:string;category:string;description:string;fields:Field[];is_active?:boolean;submission_count?:number}; type Submission={id:string;title:string;employee?:string;status:string;payload:Record<string,string>;created_at:string};
 let templates=$state<Template[]>([]), submissions=$state<Submission[]>([]), title=$state(''),category=$state('general'),description=$state(''),fieldLines=$state('Lokasi|text|required\nJenis|select|required|Audit,Instalasi\nCatatan|textarea|optional'),error=$state(''),loading=$state(true),saving=$state(false);
 function fields():Field[]{return fieldLines.split(/\r?\n/).map((line,index)=>{const [label='',kind='text',required='',options='']=line.split('|').map(x=>x.trim());return {key:label.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')||`field_${index+1}`,label,kind:kind as Field['kind'],required:['required','wajib','yes','true','1'].includes(required.toLowerCase()),options:options.split(',').map(x=>x.trim()).filter(Boolean)};}).filter(field=>field.label);}
 async function load(){loading=true;error='';try{const data=await request<{templates:Template[];submissions:Submission[]}>('/v1/admin/custom-forms');templates=data.templates;submissions=data.submissions;}catch(cause){error=cause instanceof Error?cause.message:'Custom forms tidak dapat dimuat.';}finally{loading=false;}}
 async function create(){saving=true;error='';try{await request('/v1/admin/custom-forms',{method:'POST',body:JSON.stringify({title,category,description,fields:fields()})});title='';description='';await load();}catch(cause){error=cause instanceof Error?cause.message:'Template tidak dapat dibuat.';}finally{saving=false;}}
 onMount(load);
</script>
<svelte:head><title>Custom forms · PasPapan</title></svelte:head><main class="workspace-page" id="main-content" tabindex="-1"><PageHeader title="Custom forms" description="Buat formulir kerja terarah, lalu tinjau respons tanpa membebani workflow lain." backHref="/admin/dashboard"/>{#if error}<p class="alert">{error}</p>{/if}<div class="layout"><section class="panel"><h2>Template baru</h2><form novalidate onsubmit={(e)=>{e.preventDefault();create();}}><input bind:value={title} maxlength="180" placeholder="Nama formulir" required/><input bind:value={category} maxlength="80" placeholder="Kategori" required/><textarea bind:value={description} maxlength="1000" placeholder="Deskripsi singkat"></textarea><label>Field — format: Label | type | required/optional | opsi select<textarea bind:value={fieldLines} rows="6" maxlength="5000" required></textarea></label><button disabled={saving}>Buat template</button></form></section><section class="panel"><header><h2>Template aktif</h2><RefreshButton onclick={load} label="Muat ulang"/></header>{#each templates as template (template.id)}<article><strong>{template.title}</strong><small>{template.category} · {template.fields.length} field · {template.submission_count ?? 0} respons</small><p>{template.description}</p></article>{:else}<p class="muted">Belum ada template.</p>{/each}</section></div><section class="panel"><h2>Submission terbaru</h2>{#each submissions as submission (submission.id)}<article><strong>{submission.title}</strong><small>{submission.employee ?? 'Karyawan'} · {new Date(submission.created_at).toLocaleString('id-ID')} · {submission.status}</small><p>{Object.entries(submission.payload).map(([key,value])=>`${key}: ${value}`).join(' · ')}</p></article>{:else}<p class="muted">Belum ada submission.</p>{/each}</section></main><style>.workspace-page,.layout{display:grid;gap:12px}.layout{grid-template-columns:minmax(280px,.8fr) minmax(0,1.2fr)}.panel{padding:16px;border-radius:var(--radius)}form{display:grid;gap:9px}label{font-size:12px;color:var(--muted);display:grid;gap:5px}textarea{min-height:70px;resize:vertical}header{display:flex;justify-content:space-between;align-items:center}h2{font-size:15px;margin:0 0 10px}article{padding:10px 0;border-top:1px solid var(--line)}article:first-of-type{border-top:0}small,p{display:block;margin:4px 0 0;color:var(--muted);font-size:12px}.alert{color:var(--danger);margin:0;font-size:12px}@media(max-width:720px){.layout{grid-template-columns:1fr}}</style>
